Modular Monolith.diagram:
@startuml
!include https://raw.githubusercontent.com/plantuml-stdlib/C4-PlantUML/master/C4_Component.puml
LAYOUT_WITH_LEGEND()

Container_Boundary("Modular Monolith", "Modular Monolith") {
    Component(Claims Processing Module, "Claims Processing Module", "C# / .NET Core", "Encapsulates core business logic and rules for online claims and adjuster workflows.")
    Component(Data Access Layer, "Data Access Layer", "Entity Framework Core / TCP/TLS", "Persists state to Azure Cosmos DB and caches read models via Redis.")
    Component(Integration Outbox Service, "Integration Outbox Service", ".NET Core / AMQP", "Publishes claim events asynchronously to Azure Service Bus for synchronization with the ACL.")
    Component(Secret Management Client, "Secret Management Client", "Azure SDK for .NET / HTTPS", "Retrieves secrets securely from Azure Key Vault.")
}

Rel(Claims Processing Module, Data Access Layer, "Persists state and caches read models via", "TCP/TLS")
Rel(Claims Processing Module, Integration Outbox Service, "Dispatches domain events to", "AMQP")
Rel(Claims Processing Module, Secret Management Client, "Requests runtime secrets from", "HTTPS")
@enduml

Anti-Corruption Layer (ACL).diagram:
@startuml
!include https://raw.githubusercontent.com/plantuml-stdlib/C4-PlantUML/master/C4_Component.puml
LAYOUT_WITH_LEGEND()

Container_Boundary(acl, "Anti-Corruption Layer (ACL)") {
    Component(TransactionalOutboxAndDeDuplicationEngine, "Transactional Outbox & De-duplication Engine", "Redis, .NET / C#", "Manages reliable messaging and idempotency via Redis.")
    Component(DataTransformationAndMappingLayer, "Data Transformation & Mapping Layer", ".NET / C#, Pact", "Translates legacy COBOL copybooks into modern domain events and enforces payload validation.")
    Component(ResilienceAndRoutingManager, "Resilience & Routing Manager", ".NET / C#, Polly", "Implements Circuit Breakers, Feature Flags, and declarative routing rules.")
    Component(MonitoringAndDiagnostics, "Monitoring & Diagnostics", "Azure Monitor, OpenTelemetry", "Handles distributed tracing, health check probes, and Dead Letter Queue (DLQ) operations.")
}

Rel(ResilienceAndRoutingManager, DataTransformationAndMappingLayer, "Routes processed requests to transformation", "")
Rel(DataTransformationAndMappingLayer, TransactionalOutboxAndDeDuplicationEngine, "Saves outbox state and checks idempotency", "")

@enduml

Azure Service Bus.diagram:
@startuml
!include https://raw.githubusercontent.com/plantuml-stdlib/C4-PlantUML/master/C4_Component.puml
LAYOUT_WITH_LEGEND()

title Component diagram for the Azure Service Bus container

Container_Boundary(azure_service_bus, "Azure Service Bus") {
    Component(Claim Routing Engine, "Claim Routing Engine", "Azure Service Bus Topics", "Routes claim messages asynchronously using a topic-per-claim-type strategy.")
    Component(Message Delivery Worker, "Message Delivery Worker", "AMQP Protocol Handler", "Ensures guaranteed at-least-once delivery and manages competing consumers for zero data loss.")
}

Rel(Claim Routing Engine, Message Delivery Worker, "Dispatches claim messages to", "AMQP")

@enduml

